async function promiseAlert(expectedSender, expectedName) {
  const alert = await TestUtils.waitForCondition(
    () => MockAlertsService.alert,
    `waiting for a notification about ${expectedName}`
  );
  Assert.stringContains(
    alert.text,
    `from "${expectedSender}"`,
    `notification should be about a message from ${expectedSender}`
  );
  Assert.stringContains(
    alert.name.toLowerCase(),
    expectedName.toLowerCase(),
    `notification should be about ${expectedName}`
  );

  MockAlertsService.callbacks.onAlertFinished();
  MockAlertsService.reset();
}

/**
 * Waits 500ms and reports a failure if the alerts service is called.
 */
async function promiseNoAlert() {
  // There should be no notification here. Wait a bit to be sure.
  // eslint-disable-next-line mozilla/no-arbitrary-setTimeout
  await new Promise(resolve => setTimeout(resolve, 500));
  Assert.ok(!MockAlertsService.alert, "there should be no notification");
}

class MockOSIntegration {
  QueryInterface = ChromeUtils.generateQI(interfaces);

  static _inDoNotDisturbMode = false;

  updateUnreadCount() {}
  onExit() {}
  hideWindow() {}
  showWindow() {}
  get isInDoNotDisturbMode() {
    return MockOSIntegration._inDoNotDisturbMode;
  }
}

add_setup(function () {
  // We must mock out the OS integration for all of these tests, because (at
  // least on Windows) the CI runs tests in Do Not Disturb mode, and we don't
  // display notifications in Do Not Disturb mode.
  const osIntegration = new MockObjectRegisterer(
    "@mozilla.org/messenger/osintegration;1",
    MockOSIntegration
  );
  osIntegration.register();
